startup_tenant_id=#{row.startupTenantId,jdbcType=VARCHAR},startup_workspace_id=#{row.startupWorkspaceId,jdbcType=VARCHAR},last_tenant_id=#{row.lastTenantId,jdbcType=VARCHAR},last_workspace_id=#{row.lastWorkspaceId,jdbcType=VARCHAR},favorites=#{row.favorites},version=#{row.version}
WHERE subject_id=#{row.subjectId} AND version=#{expected} AND default_tenant_id=#{row.defaultTenantId} AND
default_workspace_id=#{row.defaultWorkspaceId}
